import pyomo.environ as pyo

DATA = {
    "pills": ["Zodiac", "Sunny"],
    "nutrients": ["Z1", "D3"],
    # grams of each nutrient per pill of each pill type
    "content": {
        ("Zodiac", "Z1"): 1.3,
        ("Sunny", "Z1"): 1.2,
        ("Zodiac", "D3"): 1.5,
        ("Sunny", "D3"): 5.0,
    },
    # cost per pill
    "cost": {
        "Zodiac": 1.0,
        "Sunny": 3.0,
    },
    # minimum daily requirement (grams) per nutrient
    "requirement": {
        "Z1": 5.0,
        "D3": 10.0,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=d["pills"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # Variables: number of pills of each type taken daily (LP -> continuous)
    model.pills = pyo.Var(model.P, within=pyo.NonNegativeReals)

    # Objective: minimize total daily cost
    def obj_rule(m):
        return sum(d["cost"][p] * m.pills[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraints: meet the minimum requirement for each nutrient
    def nutrient_req_rule(m, n):
        return sum(d["content"][(p, n)] * m.pills[p] for p in m.P) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_req_rule)

    return model


