import pyomo.environ as pyo

DATA = {
    # Sets
    "PILLS": ["Zodiac", "Sunny"],
    "MEDS": ["Z1", "D3"],

    # Daily minimum requirements (grams) per medicine
    "required": {
        "Z1": 5,
        "D3": 10,
    },

    # Content (grams) of medicine m in one pill of type i
    "content": {
        ("Zodiac", "Z1"): 1.3,
        ("Sunny",  "Z1"): 1.2,
        ("Zodiac", "D3"): 1.5,
        ("Sunny",  "D3"): 5,
    },

    # Cost per pill ($)
    "cost": {
        "Zodiac": 1,
        "Sunny": 3,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.PILLS = pyo.Set(initialize=d["PILLS"])
    model.MEDS = pyo.Set(initialize=d["MEDS"])

    # Decision variables: number of pills of each type (continuous, nonnegative)
    model.x = pyo.Var(model.PILLS, within=pyo.NonNegativeReals, bounds=(0, None))

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.PILLS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: each medicine's daily requirement must be met
    def req_rule(m, n):
        return sum(
            d["content"][(i, n)] * m.x[i] for i in m.PILLS
        ) >= d["required"][n]

    model.req = pyo.Constraint(model.MEDS, rule=req_rule)

    return model
